// Byte / UTF-8 helpers. Hand-rolled: no TextEncoder/TextDecoder.

const REPLACEMENT = 0xfffd;

/**
 * Encode a JS string to UTF-8 bytes.
 * Surrogate pairs are combined; lone surrogates become U+FFFD.
 * @param {string} str
 * @returns {Uint8Array}
 */
export function encodeUtf8(str) {
  const s = String(str);
  const out = [];
  for (let i = 0; i < s.length; i++) {
    let cp = s.charCodeAt(i);
    if (cp >= 0xd800 && cp <= 0xdbff) {
      // High surrogate: needs a following low surrogate.
      const next = i + 1 < s.length ? s.charCodeAt(i + 1) : -1;
      if (next >= 0xdc00 && next <= 0xdfff) {
        cp = 0x10000 + ((cp - 0xd800) << 10) + (next - 0xdc00);
        i++;
      } else {
        cp = REPLACEMENT;
      }
    } else if (cp >= 0xdc00 && cp <= 0xdfff) {
      // Unpaired low surrogate.
      cp = REPLACEMENT;
    }

    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f),
      );
    }
  }
  return new Uint8Array(out);
}

function pushCodePoint(parts, cp) {
  if (cp < 0x10000) {
    parts.push(String.fromCharCode(cp));
  } else {
    const v = cp - 0x10000;
    parts.push(String.fromCharCode(0xd800 + (v >> 10), 0xdc00 + (v & 0x3ff)));
  }
}

/**
 * Decode UTF-8 bytes to a JS string. Malformed input yields U+FFFD.
 * @param {Uint8Array|Array<number>} bytes
 * @returns {string}
 */
export function decodeUtf8(bytes) {
  const b = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  const parts = [];
  let i = 0;
  while (i < b.length) {
    const b0 = b[i];
    let cp = -1;
    let need = 0;
    let min = 0;

    if (b0 < 0x80) {
      cp = b0;
      need = 0;
      min = 0;
    } else if (b0 >= 0xc2 && b0 <= 0xdf) {
      cp = b0 & 0x1f;
      need = 1;
      min = 0x80;
    } else if (b0 >= 0xe0 && b0 <= 0xef) {
      cp = b0 & 0x0f;
      need = 2;
      min = 0x800;
    } else if (b0 >= 0xf0 && b0 <= 0xf4) {
      cp = b0 & 0x07;
      need = 3;
      min = 0x10000;
    } else {
      // 0x80-0xc1 (continuation or overlong lead) and 0xf5-0xff.
      parts.push(String.fromCharCode(REPLACEMENT));
      i++;
      continue;
    }

    let ok = true;
    let j = 1;
    for (; j <= need; j++) {
      const bn = i + j < b.length ? b[i + j] : -1;
      if (bn < 0x80 || bn > 0xbf) {
        ok = false;
        break;
      }
      cp = (cp << 6) | (bn & 0x3f);
    }

    if (!ok) {
      // Consume the lead plus however many valid continuations we saw.
      parts.push(String.fromCharCode(REPLACEMENT));
      i += j;
      continue;
    }

    if (cp < min || cp > 0x10ffff || (cp >= 0xd800 && cp <= 0xdfff)) {
      parts.push(String.fromCharCode(REPLACEMENT));
    } else {
      pushCodePoint(parts, cp);
    }
    i += need + 1;
  }
  return parts.join('');
}

/**
 * Concatenate byte chunks.
 * @param {...(Uint8Array|Array<number>)} chunks
 * @returns {Uint8Array}
 */
export function concatBytes(...chunks) {
  let total = 0;
  for (let i = 0; i < chunks.length; i++) total += chunks[i].length;
  const out = new Uint8Array(total);
  let off = 0;
  for (let i = 0; i < chunks.length; i++) {
    const c = chunks[i];
    for (let j = 0; j < c.length; j++) out[off + j] = c[j] & 0xff;
    off += c.length;
  }
  return out;
}

/**
 * Length-checked, constant-time-ish byte comparison.
 * @param {Uint8Array|Array<number>} a
 * @param {Uint8Array|Array<number>} b
 * @returns {boolean}
 */
export function bytesEqual(a, b) {
  if (!a || !b || a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= (a[i] ^ b[i]) & 0xff;
  return diff === 0;
}

// SHA-256 (FIPS 180-4), 32-bit arithmetic only.

