const IV = new Uint32Array([
  0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
  0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
]);

const rotr = (x, n) => ((x >>> n) | (x << (32 - n))) >>> 0;

/**
 * @param {Uint8Array|Array<number>} bytes
 * @returns {Uint8Array} 32-byte digest
 */
export function sha256(bytes) {
  const msg = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  const len = msg.length;

  // Padded length: message + 0x80 + zeros + 8-byte length, multiple of 64.
  const padded = new Uint8Array(((len + 9 + 63) & ~63) >>> 0);
  padded.set(msg, 0);
  padded[len] = 0x80;

  // 64-bit big-endian bit length as two 32-bit halves (exact for len < 2^53).
  const hiBits = Math.floor(len / 0x20000000); // len * 8 / 2^32
  const loBits = (len * 8) >>> 0;
  const tail = padded.length - 8;
  padded[tail] = (hiBits >>> 24) & 0xff;
  padded[tail + 1] = (hiBits >>> 16) & 0xff;
  padded[tail + 2] = (hiBits >>> 8) & 0xff;
  padded[tail + 3] = hiBits & 0xff;
  padded[tail + 4] = (loBits >>> 24) & 0xff;
  padded[tail + 5] = (loBits >>> 16) & 0xff;
  padded[tail + 6] = (loBits >>> 8) & 0xff;
  padded[tail + 7] = loBits & 0xff;

  const H = new Uint32Array(IV);
  const W = new Uint32Array(64);

  for (let off = 0; off < padded.length; off += 64) {
    for (let t = 0; t < 16; t++) {
      const i = off + t * 4;
      W[t] =
        ((padded[i] << 24) |
          (padded[i + 1] << 16) |
          (padded[i + 2] << 8) |
          padded[i + 3]) >>>
        0;
    }
    for (let t = 16; t < 64; t++) {
      const w15 = W[t - 15];
      const w2 = W[t - 2];
      const s0 = (rotr(w15, 7) ^ rotr(w15, 18) ^ (w15 >>> 3)) >>> 0;
      const s1 = (rotr(w2, 17) ^ rotr(w2, 19) ^ (w2 >>> 10)) >>> 0;
      W[t] = (W[t - 16] + s0 + W[t - 7] + s1) >>> 0;
    }

    let a = H[0], b = H[1], c = H[2], d = H[3];
    let e = H[4], f = H[5], g = H[6], h = H[7];

    for (let t = 0; t < 64; t++) {
      const S1 = (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) >>> 0;
      const ch = ((e & f) ^ (~e & g)) >>> 0;
      const t1 = (h + S1 + ch + K[t] + W[t]) >>> 0;
      const S0 = (rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) >>> 0;
      const maj = ((a & b) ^ (a & c) ^ (b & c)) >>> 0;
      const t2 = (S0 + maj) >>> 0;

      h = g;
      g = f;
      f = e;
      e = (d + t1) >>> 0;
      d = c;
      c = b;
      b = a;
      a = (t1 + t2) >>> 0;
    }

    H[0] = (H[0] + a) >>> 0;
    H[1] = (H[1] + b) >>> 0;
    H[2] = (H[2] + c) >>> 0;
    H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0;
    H[5] = (H[5] + f) >>> 0;
    H[6] = (H[6] + g) >>> 0;
    H[7] = (H[7] + h) >>> 0;
  }

  const out = new Uint8Array(SHA256_DIGEST_SIZE);
  for (let i = 0; i < 8; i++) {
    const v = H[i];
    out[i * 4] = (v >>> 24) & 0xff;
    out[i * 4 + 1] = (v >>> 16) & 0xff;
    out[i * 4 + 2] = (v >>> 8) & 0xff;
    out[i * 4 + 3] = v & 0xff;
  }
  return out;
}

const HEX = '0123456789abcdef';

/**
 * @param {Uint8Array|Array<number>} bytes
 * @returns {string} lowercase hex digest
 */
export function sha256Hex(bytes) {
  const d = sha256(bytes);
  let s = '';
  for (let i = 0; i < d.length; i++) {
    s += HEX[(d[i] >>> 4) & 0x0f] + HEX[d[i] & 0x0f];
  }
  return s;
}

