const IV384 = [
  0xcbbb9d5dc1059ed8n, 0x629a292a367cd507n, 0x9159015a3070dd17n, 0x152fecd8f70e5939n,
  0x67332667ffc00b31n, 0x8eb44a8768581511n, 0xdb0c2e0d64f98fa7n, 0x47b5481dbefa4fa4n,
];

const rotr = (x, n) => (((x >> n) | (x << (64n - n))) & MASK);

function core(bytes, iv, outLen) {
  const msg = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  const len = msg.length;

  // message + 0x80 + zeros + 16-byte length, multiple of 128.
  const total = Math.ceil((len + 17) / 128) * 128;
  const padded = new Uint8Array(total);
  padded.set(msg, 0);
  padded[len] = 0x80;

  // 128-bit big-endian bit length; only the low 64 bits are ever nonzero here.
  let bits = BigInt(len) * 8n;
  for (let i = total - 1; i >= total - 16; i--) {
    padded[i] = Number(bits & 0xffn);
    bits >>= 8n;
  }

  const H = iv.slice();
  const W = new Array(80);

  for (let off = 0; off < total; off += 128) {
    for (let t = 0; t < 16; t++) {
      let v = 0n;
      const i = off + t * 8;
      for (let k = 0; k < 8; k++) v = (v << 8n) | BigInt(padded[i + k]);
      W[t] = v;
    }
    for (let t = 16; t < 80; t++) {
      const w15 = W[t - 15];
      const w2 = W[t - 2];
      const s0 = rotr(w15, 1n) ^ rotr(w15, 8n) ^ (w15 >> 7n);
      const s1 = rotr(w2, 19n) ^ rotr(w2, 61n) ^ (w2 >> 6n);
      W[t] = (W[t - 16] + s0 + W[t - 7] + s1) & MASK;
    }

    let a = H[0], b = H[1], c = H[2], d = H[3];
    let e = H[4], f = H[5], g = H[6], h = H[7];

    for (let t = 0; t < 80; t++) {
      const S1 = rotr(e, 14n) ^ rotr(e, 18n) ^ rotr(e, 41n);
      const ch = (e & f) ^ (~e & MASK & g);
      const t1 = (h + S1 + ch + K[t] + W[t]) & MASK;
      const S0 = rotr(a, 28n) ^ rotr(a, 34n) ^ rotr(a, 39n);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) & MASK;

      h = g;
      g = f;
      f = e;
      e = (d + t1) & MASK;
      d = c;
      c = b;
      b = a;
      a = (t1 + t2) & MASK;
    }

    H[0] = (H[0] + a) & MASK;
    H[1] = (H[1] + b) & MASK;
    H[2] = (H[2] + c) & MASK;
    H[3] = (H[3] + d) & MASK;
    H[4] = (H[4] + e) & MASK;
    H[5] = (H[5] + f) & MASK;
    H[6] = (H[6] + g) & MASK;
    H[7] = (H[7] + h) & MASK;
  }

  const full = new Uint8Array(64);
  for (let i = 0; i < 8; i++) {
    let v = H[i];
    for (let k = 7; k >= 0; k--) {
      full[i * 8 + k] = Number(v & 0xffn);
      v >>= 8n;
    }
  }
  return outLen === 64 ? full : full.slice(0, outLen);
}

