 * @param {Uint8Array|Array<number>} bytes
 * @returns {Uint8Array} 64-byte digest
 */
export function sha512(bytes) {
  return core(bytes, IV512, 64);
}

/**
 * @param {Uint8Array|Array<number>} bytes
 * @returns {Uint8Array} 48-byte digest
 */
export function sha384(bytes) {
  return core(bytes, IV384, 48);
}

// HMAC (RFC 2104) over any of the local hash functions.

import { sha256, SHA256_BLOCK_SIZE } from './sha256.mjs';
import { sha384, sha512, SHA512_BLOCK_SIZE } from './sha512.mjs';

/**
 * @param {(b: Uint8Array) => Uint8Array} hashFn
 * @param {number} blockSize
 * @param {Uint8Array|Array<number>} keyBytes
 * @param {Uint8Array|Array<number>} messageBytes
 * @returns {Uint8Array}
 */
export function hmac(hashFn, blockSize, keyBytes, messageBytes) {
  let key = keyBytes instanceof Uint8Array ? keyBytes : new Uint8Array(keyBytes || []);
  const msg =
    messageBytes instanceof Uint8Array ? messageBytes : new Uint8Array(messageBytes || []);

  if (key.length > blockSize) key = hashFn(key);

  const ipad = new Uint8Array(blockSize + msg.length);
  const opadKey = new Uint8Array(blockSize);
  for (let i = 0; i < blockSize; i++) {
    const k = i < key.length ? key[i] : 0;
    ipad[i] = k ^ 0x36;
    opadKey[i] = k ^ 0x5c;
  }
  ipad.set(msg, blockSize);

  const inner = hashFn(ipad);
  const outer = new Uint8Array(blockSize + inner.length);
  outer.set(opadKey, 0);
  outer.set(inner, blockSize);
  return hashFn(outer);
}

/**
 * @param {Uint8Array|Array<number>} keyBytes
 * @param {Uint8Array|Array<number>} messageBytes
 * @returns {Uint8Array}
 */
export function hmacSha256(keyBytes, messageBytes) {
  return hmac(sha256, SHA256_BLOCK_SIZE, keyBytes, messageBytes);
}

/**
 * @param {Uint8Array|Array<number>} keyBytes
 * @param {Uint8Array|Array<number>} messageBytes
 * @returns {Uint8Array}
 */
export function hmacSha384(keyBytes, messageBytes) {
  return hmac(sha384, SHA512_BLOCK_SIZE, keyBytes, messageBytes);
}

/**
 * @param {Uint8Array|Array<number>} keyBytes
 * @param {Uint8Array|Array<number>} messageBytes
 * @returns {Uint8Array}
 */
export function hmacSha512(keyBytes, messageBytes) {
  return hmac(sha512, SHA512_BLOCK_SIZE, keyBytes, messageBytes);
}

